    ["src/Main.lua"] = [[
return function(context)
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local UserInputService = game:GetService("UserInputService")

    local LocalPlayer = Players.LocalPlayer
    local Config = context.Config
    local Connections = context.Connections
    local PlayerCache = context.PlayerCache
    local Targeting = context.Targeting
    local Overlay = context.Overlay
    local Gui = context.Gui
    local VersionCheck = context.VersionCheck
    local Weapons = context.Weapons
    local Compatibility = context.Compatibility
    local renderStepName = "CometPrivateMain"

    local Main = {
        running = false
    }
    local lastOverlayUpdate = 0
    local errorState = {
        Overlay = {Count = 0, LastWarn = 0, Disabled = false},
        Targeting = {Count = 0, LastWarn = 0, Disabled = false}
    }

    context.LocalCharacter = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()

    local function saveConfig()
        if Gui and Gui.saveConfig then
            Gui.saveConfig()
        end
    end

    local function focusedTextBox()
        local ok, result = pcall(function()
            return UserInputService:GetFocusedTextBox()
        end)

        return ok and result ~= nil
    end

    local function keyCodeFromName(name)
        if type(name) ~= "string" or name == "" then
            return nil
        end

        local ok, keyCode = pcall(function()
            return Enum.KeyCode[name]
        end)

        if ok then
            return keyCode
        end

        return nil
    end

    local function mouseInputFromBind(bind)
        if bind == "MB1" or bind == "MouseButton1" then
            return Enum.UserInputType.MouseButton1
        elseif bind == "MB2" or bind == "MouseButton2" then
            return Enum.UserInputType.MouseButton2
        elseif bind == "MB3" or bind == "MouseButton3" then
            return Enum.UserInputType.MouseButton3
        end

        return nil
    end

    local function inputMatches(input, bind)
        local mouseInput = mouseInputFromBind(bind)

        if mouseInput then
            return input.UserInputType == mouseInput
        end

        local keyCode = keyCodeFromName(bind)

        return keyCode ~= nil and input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == keyCode
    end

    local function bindingDown(bind)
        local mouseInput = mouseInputFromBind(bind)

        if mouseInput then
            local ok, result = pcall(function()
                return UserInputService:IsMouseButtonPressed(mouseInput)
            end)

            return ok and result
        end

        local keyCode = keyCodeFromName(bind)

        if keyCode then
            local ok, result = pcall(function()
                return UserInputService:IsKeyDown(keyCode)
            end)

            return ok and result
        end

        return false
    end

    local function currentAimMode()
        local mode = Config.Input and Config.Input.AimMode or Config.Feature1.AimMode or "Hold"

        if mode ~= "Hold" and mode ~= "Toggle" and mode ~= "Always" then
            mode = "Hold"
        end

        Config.Feature1.AimMode = mode

        return mode
    end

    local function clearTarget()
        if Targeting then
            Targeting.current = nil
        end
    end

    local function syncAimState()
        if not Config.Feature1.Enabled then
            Config.Feature1.Active = false
            clearTarget()
            return
        end

        local mode = currentAimMode()

        if mode == "Always" then
            Config.Feature1.Active = true
        elseif mode == "Hold" then
            Config.Feature1.Active = bindingDown(Config.Input.AimBind)
        end

        if not Config.Feature1.Active then
            clearTarget()
        end
    end

    local function toggleOverlay()
        Config.UI.Enabled = not Config.UI.Enabled

        if not Config.UI.Enabled and Overlay then
            Overlay.hideAll()
        end

        if Gui and Gui.refresh then
            Gui.refresh()
        end

        saveConfig()
    end

    local function describeTarget(target)
        if not target then
            return "none"
        end

        if target.Player then
            return target.Player.Name
        end

        if target.Character then
            return target.Character.Name
        end

        return "unknown"
    end

    local function rememberRuntimeError(name, err)
        local state = errorState[name]

        if not state then
            return
        end

        state.Count += 1

        local diagnostics = context.Diagnostics

        if diagnostics then
            diagnostics.Runtime = diagnostics.Runtime or {}
            diagnostics.Runtime.LastError = tostring(name) .. ": " .. tostring(err)
            diagnostics.Runtime[name .. "Errors"] = state.Count
        end

        local now = os.clock()

        if now - state.LastWarn >= 5 then
            state.LastWarn = now
            warn("Comet " .. name .. " error: " .. tostring(err))
        end

        if state.Count >= 10 then
            state.Disabled = true
            warn("Comet " .. name .. " disabled after repeated runtime errors.")
        end
    end

    local function clearRuntimeError(name)
        local state = errorState[name]

        if state then
            state.Count = 0
        end
    end

    local function runSafe(name, callback)
        local state = errorState[name]

        if state and state.Disabled then
            return false, nil
        end

        local ok, result = pcall(callback)

        if ok then
            clearRuntimeError(name)
            return true, result
        end

        rememberRuntimeError(name, result)
        return false, nil
    end

    local function updateRuntimeDiagnostics(startedAt, overlayStartedAt, overlayFinishedAt, targetStartedAt, targetFinishedAt, target)
        local diagnostics = context.Diagnostics

        if not diagnostics then
            return
        end

        local runtime = diagnostics.Runtime or {}
        diagnostics.Runtime = runtime

        local finishedAt = os.clock()
        local lastFrameAt = runtime.LastFrameAt

        if lastFrameAt and finishedAt > lastFrameAt then
            runtime.Fps = 1 / (finishedAt - lastFrameAt)
        end

        runtime.LastFrameAt = finishedAt
        runtime.FrameMs = (finishedAt - startedAt) * 1000
        runtime.OverlayMs = overlayFinishedAt and overlayStartedAt and (overlayFinishedAt - overlayStartedAt) * 1000 or 0
        runtime.TargetingMs = targetFinishedAt and targetStartedAt and (targetFinishedAt - targetStartedAt) * 1000 or 0
        runtime.LastTarget = describeTarget(target)
        runtime.CachedModels = Targeting and Targeting.models and #Targeting.models or 0
        runtime.AimActive = Config.Feature1.Active
        runtime.OverlayEnabled = Config.UI.Enabled
    end

    local function panicStop()
        Config.Feature1.Active = false
        clearTarget()

        if Main.stop then
            Main.stop()
        end
    end

    local function onInputBegan(input)
        if focusedTextBox() then
            return
        end

        if Config.Input and inputMatches(input, Config.Input.OverlayBind) then
            toggleOverlay()
            return
        end

        if Config.Input and inputMatches(input, Config.Input.PanicBind) then
            panicStop()
            return
        end

        if Config.Input and inputMatches(input, Config.Input.AimBind) then
            local mode = currentAimMode()

            if mode == "Toggle" then
                Config.Feature1.Active = not Config.Feature1.Active

                if not Config.Feature1.Active then
                    clearTarget()
                end
            elseif mode == "Hold" then
                Config.Feature1.Active = true
            end
        end
    end

    local function onInputEnded(input)
        if Config.Input and inputMatches(input, Config.Input.AimBind) and currentAimMode() == "Hold" then
            Config.Feature1.Active = false
            clearTarget()
        end
    end

    local function step()
        local startedAt = os.clock()

        syncAimState()

        local overlayStartedAt = nil
        local overlayFinishedAt = nil
        local now = os.clock()
        local overlayRate = math.clamp(tonumber(Config.UI and Config.UI.OverlayRate) or 30, 5, 60)

        if Overlay and Overlay.updateAll and now - lastOverlayUpdate >= 1 / overlayRate then
            lastOverlayUpdate = now
            overlayStartedAt = os.clock()
            runSafe("Overlay", function()
                Overlay.updateAll()
            end)
            overlayFinishedAt = os.clock()
        end

        local targetStartedAt = os.clock()
        local target = nil

        if Targeting and Targeting.update then
            local _, result = runSafe("Targeting", function()
                return Targeting.update()
            end)

            target = result
        end

        local targetFinishedAt = os.clock()

        updateRuntimeDiagnostics(startedAt, overlayStartedAt, overlayFinishedAt, targetStartedAt, targetFinishedAt, target)
    end

    local function supports(capability)
        return not Compatibility or Compatibility.supports(capability)
    end

    local function setLoopDiagnostic(mode, detail)
        if not context.Diagnostics then
            return
        end

        context.Diagnostics.Runtime = context.Diagnostics.Runtime or {}
        context.Diagnostics.Runtime.Loop = mode
        context.Diagnostics.Runtime.LoopDetail = detail
    end

    local function connectSignalLoop(signalName)
        local ok, connection = pcall(function()
            return RunService[signalName]:Connect(step)
        end)

        if ok and connection then
            Connections.add("RenderLoop", connection)
            setLoopDiagnostic(signalName, "connected through RunService." .. signalName)
            return true
        end

        return false, connection
    end

    local function bindRenderLoop()
        if supports("BindToRenderStep") then
            pcall(function()
                RunService:UnbindFromRenderStep(renderStepName)
            end)

            local bound, err = pcall(function()
                RunService:BindToRenderStep(renderStepName, Enum.RenderPriority.Camera.Value + 1, step)
            end)

            if bound then
                Connections.add("RenderLoop", {
                    Disconnect = function()
                        pcall(function()
                            RunService:UnbindFromRenderStep(renderStepName)
                        end)
                    end
                })
                setLoopDiagnostic("BindToRenderStep", "bound after camera update priority")
                return true
            end

            setLoopDiagnostic("BindToRenderStepFailed", tostring(err))
        end

        if supports("RenderStepped") then
            local connected = connectSignalLoop("RenderStepped")

            if connected then
                return true
            end
        end

        if supports("Heartbeat") then
            local connected = connectSignalLoop("Heartbeat")

            if connected then
                return true
            end
        end

        setLoopDiagnostic("None", "no RunService frame signal could be connected")
        warn("Comet render loop unavailable; overlay and targeting updates are disabled.")
        return false
    end

    function Main.start()
        if Main.running then
            return Main
        end

        Main.running = true

        if PlayerCache and PlayerCache.setupAll then
            PlayerCache.setupAll()
        end

        if Targeting and Targeting.start then
            Targeting.start()
        end

        if Weapons and Weapons.start then
            Weapons.start()
        end

        if Gui and Gui.start then
            Gui.start()
        end

        if Weapons and Weapons.syncState then
            Weapons.syncState()
        end

        if VersionCheck and VersionCheck.start then
            VersionCheck.start()
        end

        Connections.add("InputBegan", UserInputService.InputBegan:Connect(onInputBegan))
        Connections.add("InputEnded", UserInputService.InputEnded:Connect(onInputEnded))
        Connections.add("PlayerAdded", Players.PlayerAdded:Connect(function(player)
            if PlayerCache and PlayerCache.setup then
                PlayerCache.setup(player)
            end
        end))
        Connections.add("PlayerRemoving", Players.PlayerRemoving:Connect(function(player)
            if PlayerCache and PlayerCache.remove then
                PlayerCache.remove(player)
            end
        end))
        Connections.add("CharacterAdded", LocalPlayer.CharacterAdded:Connect(function(character)
            context.LocalCharacter = character
        end))
        bindRenderLoop()

        return Main
    end

    function Main.stop()
        if not Main.running then
            return Main
        end

        Main.running = false
        Config.Feature1.Active = false
        clearTarget()

        if Gui and Gui.destroy then
            Gui.destroy()
        end

        Connections.disconnectAll()

        if Targeting and Targeting.stop then
            Targeting.stop()
        end

        if Weapons and Weapons.stop then
            Weapons.stop()
        end

        if VersionCheck and VersionCheck.stop then
            VersionCheck.stop()
        end

        if Overlay and Overlay.hideAll then
            Overlay.hideAll()
        end

        if PlayerCache and PlayerCache.clear then
            PlayerCache.clear()
        end

        return Main
    end

    context.Main = Main

    return Main
end

]],
}


local DEFAULT_MANIFEST = {
    Name = "Comet",
    Version = "1.2.4",
    Build = 124,
    Channel = "stable",
    Cache = "build",
    RequiredLoader = 2,
    Modules = {
        {Name = "Version", Path = "src/core/Version.lua", Required = true},
        {Name = "Config", Path = "src/core/Config.lua", Required = true},
        {Name = "Connections", Path = "src/core/Connections.lua", Required = true},
        {Name = "ConfigMigrator", Path = "src/core/ConfigMigrator.lua", Required = true},
        {Name = "Compatibility", Path = "src/core/Compatibility.lua", Required = true},
        {Name = "PlayerCache", Path = "src/features/PlayerCache.lua", Required = true},
        {Name = "Targeting", Path = "src/features/Targeting.lua", Required = true},
        {Name = "Weapons", Path = "src/features/Weapons.lua", Required = false},
        {Name = "Overlay", Path = "src/features/Overlay.lua", Required = true},
        {Name = "UIAdapter", Path = "src/ui/UIAdapter.lua", Required = false},
        {Name = "GUI", Path = "src/ui/GUI.lua", Required = false},
        {Name = "VersionCheck", Path = "src/core/VersionCheck.lua", Required = false},
        {Name = "Main", Path = "src/Main.lua", Required = true},
    },
    UIProviders = {
        Fluent = "https://github.com/dawid-scripts/Fluent/releases/latest/download/main.lua",
        Rayfield = "https://sirius.menu/rayfield"
    }
}

local context = {
    BaseUrl = BASE_URL,
    LoaderVersion = LOADER_VERSION,
    Manifest = nil,
    Modules = {},
    Authorized = true,
    Diagnostics = {
        Boot = {
            StartedAt = os.clock(),
            FinishedAt = nil,
            Status = "Booting",
            Entries = {}
        },
        Modules = {},
        Notifications = {},
        Errors = {},
        Runtime = {}
    }
}

local function cloneArray(value)
    local copy = {}

    for index, item in ipairs(value or {}) do
        if type(item) == "table" then
            local itemCopy = {}

            for key, child in pairs(item) do
                itemCopy[key] = child
            end

            copy[index] = itemCopy
        else
            copy[index] = item
        end
    end

    return copy
end

local function cloneManifest(value)
    local copy = {}

    for key, child in pairs(value) do
        if key == "Modules" then
            copy.Modules = cloneArray(child)
        elseif key == "UIProviders" and type(child) == "table" then
            copy.UIProviders = {}

            for provider, url in pairs(child) do
                copy.UIProviders[provider] = url
            end
        else
            copy[key] = child
        end
    end

    return copy
end

local function record(level, message, data)
    local entry = {
        At = os.clock(),
        Level = level,
        Message = message,
        Data = data
    }

    table.insert(context.Diagnostics.Boot.Entries, entry)

    if level == "error" then
        table.insert(context.Diagnostics.Errors, entry)
        warn("Comet loader: " .. message)
    end

    return entry
end

local function cacheToken()
    local manifest = context.Manifest

    if manifest and manifest.Cache == "none" then
        return tostring(os.time())
    end

    if manifest and manifest.Build then
        return tostring(manifest.Build)
    end

    return tostring(os.time())
end

local function fetch(path, token)
    local query = token or cacheToken()

    if BUNDLED_SOURCES[path] then
        return true, BUNDLED_SOURCES[path]
    end

    local url = BASE_URL .. path .. "?v=" .. tostring(query)
    local lastError = nil

    for attempt = 1, FETCH_RETRIES do
        local ok, source = pcall(function()
            return game:HttpGet(url, true)
        end)

        if ok and type(source) == "string" and source ~= "" then
            return true, source
        end

        lastError = source or "empty response"

        if attempt < FETCH_RETRIES and task and task.wait then
            task.wait(0.2 * attempt)
        end
    end

    return false, tostring(lastError)
end

local function evaluateSource(path, source)
    local chunk, compileError = loadstring(source)

    if not chunk then
        return false, "compile failed: " .. tostring(compileError)
    end

    local ok, value = pcall(chunk)

    if not ok then
        return false, "runtime failed: " .. tostring(value)
    end

    return true, value
end

local function loadManifest()
    local manifest = cloneManifest(DEFAULT_MANIFEST)
    local ok, source = fetch("Manifest.lua", tostring(os.time()))

    if ok then
        local loaded, data = evaluateSource("Manifest.lua", source)

        if loaded and type(data) == "table" then
            manifest = data
            record("info", "Loaded remote manifest", {Build = manifest.Build, Version = manifest.Version})
        else
            record("error", "Manifest failed; using fallback manifest", data)
        end
    else
        record("error", "Manifest fetch failed; using fallback manifest", source)
    end

    context.Manifest = manifest

    if tonumber(manifest.RequiredLoader) and tonumber(manifest.RequiredLoader) > LOADER_VERSION then
        record("error", "Manifest requires a newer loader", {
            Required = manifest.RequiredLoader,
            Current = LOADER_VERSION
        })
        context.Diagnostics.Boot.Status = "Incompatible"
        return false
    end

    return true
end

local function runModule(module)
    local name = module.Name or module.Path
    local path = module.Path or (tostring(name) .. ".lua")
    local required = module.Required ~= false
    local status = {
        Name = name,
        Path = path,
        Required = required,
        StartedAt = os.clock(),
        FinishedAt = nil,
        Status = "Loading",
        Error = nil
    }

    context.Diagnostics.Modules[name] = status

    local fetched, source = fetch(path)

    if not fetched then
        status.Status = "FetchFailed"
        status.Error = source
        status.FinishedAt = os.clock()
        record(required and "error" or "warn", "Module fetch failed: " .. tostring(name), source)
        return not required
    end

    local loaded, value = evaluateSource(path, source)

    if not loaded then
        status.Status = "LoadFailed"
        status.Error = value
        status.FinishedAt = os.clock()
        record(required and "error" or "warn", "Module load failed: " .. tostring(name), value)
        return not required
    end

    local result = value

    if typeof(value) == "function" then
        local ok, moduleResult = pcall(value, context)

        if not ok then
            status.Status = "StartFailed"
            status.Error = moduleResult
            status.FinishedAt = os.clock()
            record(required and "error" or "warn", "Module start failed: " .. tostring(name), moduleResult)
            return not required
        end

        result = moduleResult
    end

    context.Modules[name] = result

    if name == "Version" or path:match("Version%.lua$") then
        context.Version = result
    end

    status.Status = "Loaded"
    status.FinishedAt = os.clock()

    return true
end

function context.Notify(title, content, duration, subContent)
    local entry = {
        Title = title,
        Content = content,
        SubContent = subContent,
        Duration = duration or 5,
        At = os.clock()
    }

    table.insert(context.Diagnostics.Notifications, entry)

    local gui = context.Gui

    if gui and gui.notify then
        gui.notify(title, content, duration, subContent)
    end

    return entry
end

local manifestOk = loadManifest()

if manifestOk then
    for _, module in ipairs(context.Manifest.Modules or {}) do
        if not runModule(module) then
            context.Diagnostics.Boot.Status = "Failed"
            break
        end
    end
end

if context.Diagnostics.Boot.Status ~= "Failed" and context.Diagnostics.Boot.Status ~= "Incompatible" then
    local main = context.Modules.Main

    if main and main.start then
        local ok, err = pcall(function()
            main.start()
        end)

        if ok then
            context.Diagnostics.Boot.Status = "Running"
        else
            context.Diagnostics.Boot.Status = "Failed"
            record("error", "Main start failed", err)
        end
    else
        context.Diagnostics.Boot.Status = "Failed"
        record("error", "Main module did not expose start()")
    end
end

context.Diagnostics.Boot.FinishedAt = os.clock()

return context
